INSERT OR IGNORE INTO stories(id,slug,owner_id,title,logline,genre,world_rules,visual_style,status,version,cover_url,fixture,created_at,updated_at) VALUES('last-light','the-last-light','dev-studio','The Last Light','Every night, the lighthouse answers a signal. Tonight, the signal knows her name.','Mystery','A remote coastal town in 1987. Mara Vale is the new lighthouse keeper. Elias Reed repairs the town radios. The lighthouse has been empty for twenty years. Events follow physical causality; no time travel or supernatural explanation is established. Keep the storm, the brass key, and the radio consistent.','Cinematic coastal mystery, slate teal ocean, warm amber light, natural faces, restrained 35mm film grain.','open',3,'/art/last-light.png',1,1788667200000,1788667500000);
INSERT OR IGNORE INTO stories(id,slug,owner_id,title,logline,genre,world_rules,visual_style,status,version,cover_url,fixture,created_at,updated_at) VALUES('quiet-orbit','the-quiet-orbit','dev-studio','The Quiet Orbit','An abandoned station. A garden still growing. A message that was never meant to reach Earth.','Science fiction','In 2186 a civilian research station orbits an unnamed gas giant. Botanist Inez Sol is investigating an abandoned greenhouse. Navigator Theo Ward stays in the docking bay. Communications take hours. There is no faster-than-light travel and no known alien presence.','Quiet analog science fiction, muted ochre and olive, practical lighting, glass reflections, realistic space hardware.','open',1,'/art/quiet-orbit.png',1,1788667000000,1788667100000);
INSERT OR IGNORE INTO characters(id,story_id,name,description,state,introduced_version) VALUES('mara-vale','last-light','Mara Vale','A meticulous lighthouse keeper in her thirties, with dark cropped hair and a rust-orange raincoat.','At the lighthouse entrance, holding a brass key. She has heard her name over the radio.',0);
INSERT OR IGNORE INTO characters(id,story_id,name,description,state,introduced_version) VALUES('elias-reed','last-light','Elias Reed','A patient radio repairer in his forties, with silver-rimmed glasses and a charcoal wool coat.','In the radio workshop. He knows the transmitter was disconnected twenty years ago.',2);
INSERT OR IGNORE INTO characters(id,story_id,name,description,state,introduced_version) VALUES('inez-sol','quiet-orbit','Inez Sol','A botanist in her thirties in an off-white utility spacesuit with an amber shoulder stripe.','Inside the greenhouse, with her helmet light on and an unopened research log.',0);
INSERT OR IGNORE INTO characters(id,story_id,name,description,state,introduced_version) VALUES('theo-ward','quiet-orbit','Theo Ward','A quiet navigator in his thirties with a navy flight suit and a worn canvas tool pouch.','Waiting in the docking bay. He does not know what Inez has found.',0);
INSERT OR IGNORE INTO episodes VALUES('last-light:episode:1','last-light',1,'The signal in the fog','open',30000);
INSERT OR IGNORE INTO episodes VALUES('quiet-orbit:episode:1','quiet-orbit',1,'Something is still growing','open',10000);
INSERT OR IGNORE INTO scenes(id,story_id,episode_id,version,title,summary,media_key,captions_key,thumbnail_url,duration_ms,start_ms,prompt_original,english_prompt,author_id,source,fixture,published_at) VALUES
('sample-light-1','last-light','last-light:episode:1',1,'A light where none should be','Mara arrives at the headland. A warm beacon cuts through the fog above the abandoned lighthouse.','fixture:sample','fixture:captions','/art/last-light.png',10000,0,'Studio storyboard: introduce Mara and the abandoned lighthouse.','Studio storyboard: introduce Mara and the abandoned lighthouse.','dev-studio','studio',1,1788667300000),
('sample-light-2','last-light','last-light:episode:1',2,'A voice in the static','Mara hears her name over a radio. Elias, in his workshop, discovers that the old transmitter is still disconnected.','fixture:sample','fixture:captions','/art/last-light.png',10000,10000,'Studio storyboard: a radio signal knows the keeper’s name.','Studio storyboard: a radio signal knows the keeper’s name.','dev-studio','studio',1,1788667400000),
('sample-light-3','last-light','last-light:episode:1',3,'The door below','At the lighthouse entrance, Mara discovers a narrow brass door. She still holds the key she brought from the village.','fixture:sample','fixture:captions','/art/last-light.png',10000,20000,'Studio storyboard: reveal a locked door and leave the next choice open.','Studio storyboard: reveal a locked door and leave the next choice open.','dev-studio','studio',1,1788667500000),
('sample-orbit-1','quiet-orbit','quiet-orbit:episode:1',1,'The greenhouse','Inez enters the abandoned station greenhouse. Its plants are still growing, and a sealed research log waits by the airlock.','fixture:sample','fixture:captions','/art/quiet-orbit.png',10000,0,'Studio storyboard: introduce Inez and a greenhouse that outlived its crew.','Studio storyboard: introduce Inez and a greenhouse that outlived its crew.','dev-studio','studio',1,1788667100000);
